<?php

/* @autogenerated */
declare(strict_types=1);

namespace {
    use PHPUnit\Framework\TestCase;
    use PHPUnit\Framework\Attributes\AllowMockObjectsWithoutExpectations;
    use Psr\Container\ContainerInterface;
    use Civi\Lughauth\Bootstrap\Plugin\MultiTenantPlugin;
    use Civi\Lughauth\Bootstrap\Management\Migration\MigrationManagement;
    use Civi\Lughauth\Shared\Infrastructure\AggregatedMicroPlugin;
    use Civi\Lughauth\Shared\Infrastructure\Migration\MigrationInterface;
    use Civi\Lughauth\Shared\Event\EventListenersRegistrarInterface;
    use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
    use Civi\Lughauth\Features\Access\User\Domain\Event\UserCreateEvent;
    use Civi\Lughauth\Features\Access\UserAccessTemporalCode\Domain\Event\UserAccessTemporalCodeGeneratePasswordRecoverEvent;
    use Civi\Lughauth\Features\OAuth\User\Application\Listener\NotifyLogin;
    use Civi\Lughauth\Features\OAuth\User\Application\Listener\NotifyRecover;
    use Civi\Lughauth\Features\OAuth\User\Application\Listener\NotifyCreate;
    use Civi\Lughauth\Features\OAuth\Common\Infrastructure\Driver\Management\OAuthMigrationProvider;

    /**
     * Unit tests for {@see MultiTenantPlugin}.
     */
    #[AllowMockObjectsWithoutExpectations]
    final class MultiTenantPluginUnitTest extends TestCase
    {
        /**
         * Ensures MultiTenantPlugin is an AggregatedMicroPlugin.
         */
        public function testIsAggregatedMicroPlugin(): void
        {
            $plugin = new MultiTenantPlugin();

            $this->assertInstanceOf(AggregatedMicroPlugin::class, $plugin);
        }

        /**
         * Ensures registerEvents subscribes the three notification listeners.
         */
        public function testRegisterEventsSubscribesNotificationListeners(): void
        {
            $plugin = new MultiTenantPlugin();
            $registered = [];
            $listener = new class ($registered) implements EventListenersRegistrarInterface {
                public function __construct(private array &$registered)
                {
                }

                public function registerListener(string $event, string $type, ?string $method = null): void
                {
                    $this->registered[] = [$event, $type];
                }
            };

            $plugin->registerEvents($listener);

            $this->assertContains([AuthenticationResult::class, NotifyLogin::class], $registered);
            $this->assertContains([UserCreateEvent::class, NotifyCreate::class], $registered);
            $this->assertContains([UserAccessTemporalCodeGeneratePasswordRecoverEvent::class, NotifyRecover::class], $registered);
        }

        /**
         * Ensures getManagementsInterfaces adds the OAuthMigrationProvider to MigrationManagement.
         */
        public function testGetManagementsInterfacesAddsMigrationProvider(): void
        {
            $plugin = new MultiTenantPlugin();
            $oidcProvider = $this->createMock(OAuthMigrationProvider::class);
            $migration = $this->createMock(MigrationManagement::class);
            $migration->expects($this->once())
                ->method('addProvider')
                ->with($this->identicalTo($oidcProvider));

            $container = new class ($migration, $oidcProvider) implements ContainerInterface {
                public function __construct(
                    private readonly MigrationManagement $migration,
                    private readonly MigrationInterface $oidcProvider
                ) {
                }

                public function get(string $id): mixed
                {
                    return match ($id) {
                        MigrationManagement::class => $this->migration,
                        OAuthMigrationProvider::class => $this->oidcProvider,
                        default => null,
                    };
                }

                public function has(string $id): bool
                {
                    return in_array($id, [MigrationManagement::class, OAuthMigrationProvider::class], true);
                }
            };

            $plugin->getManagementsInterfaces($container);
        }
    }
}
